import { quality } from './render-policy.js';
/* Original bound volume with an articulated cover and continuously curved paper. */
import * as T from './vendor/three.module.js';
export async function createYearbook(scene,keep,base){
 const own=x=>keep(x),group=new T.Group();scene.add(group);group.rotation.y=-.17;const loader=new T.TextureLoader();
 const load=async url=>{try{return await loader.loadAsync(url)}catch{return null}};
 const names=[['Akshara Naik','akshara-naik'],['Aamir Mir','aamir-mir'],['Arya Thomas','arya-thomas'],['Sharvanee Sonawane','sharvanee-sonawane'],['Prasanna Nage','prasanna-nage'],['Yashwanth Juluva','yashwanth-juluva']];
 const images=await Promise.all(names.map(async ([name,id])=>[name,await load(new URL(`assets/yearbook/portraits/${id}.webp`,base).href)]));
 const logo=await load(new URL('../assets/official/brand/iit-bombay-sports-bw.png',base).href);
 const makeCanvas=draw=>{const c=document.createElement('canvas');c.width=quality.lite?600:1200;c.height=quality.lite?800:1600;const ctx=c.getContext('2d');ctx.scale(c.width/1200,c.height/1600);draw(ctx,c);const t=own(new T.CanvasTexture(c));t.colorSpace=T.SRGBColorSpace;t.anisotropy=4;return t;};
 function grain(ctx,color){ctx.fillStyle=color;ctx.fillRect(0,0,1200,1600);let s=2026;for(let i=0;i<40000;i++){s=(s*1664525+1013904223)>>>0;const x=s%1200;s=(s*1664525+1013904223)>>>0;const y=s%1600;ctx.fillStyle=i%2?'#ffffff0b':'#00000009';ctx.fillRect(x,y,1,2);}}
 const coverMap=makeCanvas(ctx=>{grain(ctx,'#173f34');ctx.strokeStyle='#adbd9450';ctx.lineWidth=2;ctx.strokeRect(58,58,1084,1484);ctx.fillStyle='#d6c59c';ctx.font='32px Faktum';ctx.fillText('IIT BOMBAY SPORTS',100,132);ctx.fillText('THE CLASS OF',100,895);ctx.font='300px Faktum';ctx.fillText('2026',86,1175);ctx.font='76px Faktum';ctx.fillText('Yearbook',100,1315);ctx.font='28px Faktum';ctx.fillText('Until. Victory. Always.',100,1460);if(logo){ctx.save();ctx.globalCompositeOperation='screen';ctx.drawImage(logo.image,850,260,215,250);ctx.restore();}ctx.strokeStyle='#d6c59c';ctx.beginPath();ctx.moveTo(100,840);ctx.lineTo(1100,840);ctx.stroke();});
 const inside=makeCanvas(ctx=>{grain(ctx,'#d9dfcc');ctx.fillStyle='#173f34';ctx.font='34px Faktum';ctx.fillText('IIT BOMBAY SPORTS',100,140);ctx.font='160px Faktum';ctx.fillText('2026',90,1450);});
 const left=makeCanvas(ctx=>{grain(ctx,'#f4f1e9');ctx.fillStyle='#173f34';ctx.font='28px Faktum';ctx.fillText('SPORTS YEARBOOK',110,130);ctx.font='116px Faktum';['The people','we played','alongside.'].forEach((s,i)=>ctx.fillText(s,100,490+i*137));ctx.font='33px Faktum';ctx.fillText('The moments pass.',110,1060);ctx.fillText('The memories stay.',110,1110);ctx.strokeStyle='#173f3466';ctx.beginPath();ctx.moveTo(110,1360);ctx.lineTo(1090,1360);ctx.stroke();ctx.font='26px Faktum';ctx.fillText('CLASS OF 2026',110,1440);ctx.fillText('IIT BOMBAY',860,1440);});
 const right=makeCanvas(ctx=>{grain(ctx,'#f4f1e9');ctx.fillStyle='#173f34';ctx.font='28px Faktum';ctx.fillText('ON THE SAME SIDE.',85,120);images.forEach(([name,tex],i)=>{const x=85+(i%2)*545,y=185+Math.floor(i/2)*430;ctx.fillStyle='#d9dfcc';ctx.fillRect(x,y,485,325);if(tex){const img=tex.image;const scale=Math.max(485/img.width,325/img.height);ctx.save();ctx.beginPath();ctx.rect(x,y,485,325);ctx.clip();ctx.drawImage(img,x+(485-img.width*scale)/2,y+(325-img.height*scale)/2,img.width*scale,img.height*scale);ctx.restore();}ctx.fillStyle='#173f34';ctx.font='24px Faktum';ctx.fillText(name,x,y+365);});ctx.font='26px Faktum';ctx.fillText('2026',1000,1540);});
 const weave=document.createElement('canvas');weave.width=weave.height=256;const wctx=weave.getContext('2d');wctx.fillStyle='#888';wctx.fillRect(0,0,256,256);for(let x=0;x<256;x+=4){wctx.fillStyle='#aaa';wctx.fillRect(x,0,1,256);wctx.fillStyle='#666';wctx.fillRect(0,x,256,1);}const bump=own(new T.CanvasTexture(weave));bump.wrapS=bump.wrapT=T.RepeatWrapping;bump.repeat.set(8,8);
 const green=own(new T.MeshStandardMaterial({color:'#163a30',roughness:.86})),paper=own(new T.MeshStandardMaterial({color:'#e6e1d2',roughness:.95})),top=own(new T.MeshStandardMaterial({map:coverMap,roughness:.76,bumpMap:bump,bumpScale:.012})),end=own(new T.MeshStandardMaterial({map:inside,roughness:.9}));
 const box=(w,h,d,material,parent=group)=>{const o=new T.Mesh(own(new T.BoxGeometry(w,h,d)),material);o.castShadow=o.receiveShadow=true;parent.add(o);return o;};
 const back=box(3.45,.105,4.7,green);back.position.set(1.65,.055,0);
 const block=box(3.25,.27,4.48,paper);block.position.set(1.68,.24,0);
 for(let i=0;i<13;i++){const m=own(new T.MeshStandardMaterial({color:i%3?'#d1cbb9':'#f7f3e8',roughness:.95}));const edge=box(3.25,.004,4.48,m);edge.position.set(1.68,.12+i*.019,0);}
 const topPage=box(3.23,.016,4.46,[paper,paper,own(new T.MeshStandardMaterial({map:right,roughness:.9})),paper,paper,paper]);topPage.position.set(1.68,.388,0);
 const hinge=new T.Group();hinge.position.set(0,.42,0);group.add(hinge);
 const lid=box(3.45,.10,4.7,[green,green,top,end,green,green],hinge);lid.position.set(1.65,0,0);
 // Separate facing meshes share a continuously curved sheet; no rigid card turn.
 const geom=own(new T.PlaneGeometry(3.23,4.46,52,8));geom.rotateX(-Math.PI/2);geom.translate(1.66,0,0);const front=new T.Mesh(geom,own(new T.MeshStandardMaterial({map:left,roughness:.95,side:T.FrontSide}))),reverse=new T.Mesh(geom,own(new T.MeshStandardMaterial({map:left,roughness:.95,side:T.BackSide})));front.castShadow=reverse.castShadow=true;front.receiveShadow=reverse.receiveShadow=true;group.add(front,reverse);reverse.material.map=own(left.clone());reverse.material.map.repeat.x=-1;reverse.material.map.offset.x=1;const original=Float32Array.from(geom.attributes.position.array);
 // Green woven book ribbon hanging beyond the fore-edge.
 const ribbon=box(.11,.012,1.05,own(new T.MeshStandardMaterial({color:'#9aab80',roughness:.8})));ribbon.position.set(2.68,.115,2.55);ribbon.rotation.x=.08;
 const spine=new T.Mesh(own(new T.CylinderGeometry(.21,.21,4.68,32,1,false,0,Math.PI)),green);spine.rotation.x=Math.PI/2;spine.position.set(.015,.22,0);group.add(spine);
 const floor=new T.Mesh(own(new T.PlaneGeometry(200,200)),own(new T.ShadowMaterial({color:'#2e3928',opacity:.23})));floor.rotation.x=-Math.PI/2;floor.position.y=-.008;floor.receiveShadow=true;scene.add(floor);
 const smooth=t=>{t=Math.max(0,Math.min(1,t));return t*t*(3-2*t)};
 function pose(progress){front.visible=reverse.visible=progress>.28;hinge.rotation.z=smooth(progress/.70)*Math.PI*.995;const turn=smooth((progress-.43)/.57),a=turn*Math.PI*.995,pos=geom.attributes.position;for(let i=0;i<pos.count;i++){const u=original[i*3],v=u/3.28,angle=a-(Math.sin(turn*Math.PI)*.62*Math.sin(v*Math.PI));pos.setXYZ(i,u*Math.cos(angle),.505+u*Math.sin(angle),original[i*3+2]);}pos.needsUpdate=true;geom.computeVertexNormals();}
 pose(0);images.forEach(([,t])=>t?.dispose());logo?.dispose();return {group,pose,hinge,floor,topPage,leaves:[front,reverse],stats:{segments:52,portraits:6,originalGeometry:true}};
}
